p=Path(__file__).parent;fix=Path('/tmp/atcoder_binary_speed_20261019');tags=['before','candidate','direct4','control']
# control uses exactly the baseline executable, to measure the run-to-run variation.
report={'flags':['g++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS'],'cpu_affinity':14,'repeat':9,'control':'exact same executable as before','micro':{},'official':[]}
with open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a') as lock,open(os.devnull,'wb') as sink:
 fcntl.flock(lock,fcntl.LOCK_EX);os.sched_setaffinity(0,{14})
 for group in ['update','unique','query']:
  raw={tag:[] for tag in tags}
  for rep in range(9):
   order=tags[rep%4:]+tags[:rep%4]
   if rep%2:order=order[::-1]
   for tag in order:
    exe=p/(('before' if tag=='control' else tag)+'_'+group+'_gcc_skip')
    result=subprocess.run([str(exe)],capture_output=True,text=True,check=True)
    raw[tag].append(list(csv.DictReader(io.StringIO(result.stdout))))
   print(group,rep,flush=True)
  rows=[]
  for i,item in enumerate(raw['before'][0]):
   assert all(raw[tag][r][i]['case']==item['case'] and raw[tag][r][i]['checksum']==item['checksum'] for tag in tags for r in range(9))
   vals={tag:statistics.median(float(raw[tag][r][i]['ns_per_op']) for r in range(9)) for tag in tags}
   rows.append(dict(case=item['case'],median_ns=vals,candidate_ratio=vals['candidate']/vals['before'],direct4_ratio=vals['direct4']/vals['before'],control_ratio=vals['control']/vals['before']))
  report['micro'][group]={'rows':rows,'raw':raw}
  (p/'candidate-results.json').write_text(json.dumps(report,indent=2))
 for case in sorted((fix/'fixtures').glob('*.in')):
  raw={tag:[] for tag in tags}
  for rep in range(9):
   order=tags[rep%4:]+tags[:rep%4]
   if rep%2:order=order[::-1]
   for tag in order:
    exe=p/(('before' if tag=='control' else tag)+'_official_gcc_skip')
    with case.open('rb') as inp:
     st=time.perf_counter_ns();subprocess.run([str(exe)],stdin=inp,stdout=sink,check=True);raw[tag].append((time.perf_counter_ns()-st)/1e6)
  vals={tag:statistics.median(v) for tag,v in raw.items()}
  row=dict(case=case.name,median_ms=vals,candidate_ratio=vals['candidate']/vals['before'],direct4_ratio=vals['direct4']/vals['before'],control_ratio=vals['control']/vals['before'],raw=raw)
  report['official'].append(row);print(case.name,vals,flush=True)
  (p/'candidate-results.json').write_text(json.dumps(report,indent=2))

