   for(std::size_t k:{std::size_t{1},m.size(),std::size_t{1}+rng()%m.size()}){auto r=tr.get_kth(static_cast<std::int64_t>(k));REQUIRE(static_cast<U>(r.first)==sorted[k-1]);verify_ids(sorted[k-1],r.second);}
